def extract_total(text):
    """Pick total amount following the priority/exclusion rules.

    Within a priority group, keywords are tried in listed order; for each
    keyword we scan lines top-to-bottom. If multiple non-excluded matches
    exist, prefer one whose line explicitly marks the total as inclusive
    (e.g. `Total Includes GST`); otherwise return the first match.
    """
    lines = [ln.strip() for ln in text.splitlines()]
    uppers = [ln.upper() for ln in lines]
    for group in PRIORITY_KEYWORDS:
        for kw in group:
            incl_pick = None
            first_pick = None
            for i, u in enumerate(uppers):
                if kw not in u:
                    continue
                if line_excluded(u):
                    continue
                amt = _candidate_amount(lines, uppers, i)
                if amt is None:
                    continue
                if first_pick is None:
                    first_pick = amt
                normalized = re.sub(r'[^A-Z0-9]+', ' ', u)
                if any(m in normalized for m in INCL_MARKERS) and incl_pick is None:
                    incl_pick = amt
            if incl_pick is not None:
                return incl_pick
            if first_pick is not None:
                return first_pick
